    id SERIAL PRIMARY KEY,
    nome VARCHAR(100) NOT NULL,
    continente VARCHAR(50) NOT NULL,
    tipo_esperienza VARCHAR(50) NOT NULL,
    budget_min INTEGER NOT NULL,
    budget_max INTEGER NOT NULL,
