     -- Creazione tabella PRENOTAZIONI MISTERIOSE
-- Salva le prenotazioni dei viaggi misteriosi fatte dagli utenti
CREATE TABLE prenotazioni_misteriose (
    id SERIAL PRIMARY KEY,
    
    -- Codice univoco mostrato all'utente (es: WV-ABC1234)
    codice VARCHAR(20) NOT NULL UNIQUE,
    
    -- Collegamento all'utente che ha prenotato (foreign key verso la tabella utenti)
    id_utente BIGINT NOT NULL,
    
    -- Collegamento alla destinazione assegnata (foreign key verso destinazioni_misteriose)
    id_destinazione INTEGER,
    
    -- Criteri scelti dall'utente nel form
    continente_richiesto VARCHAR(50),
    data_partenza DATE NOT NULL,
    durata VARCHAR(20) NOT NULL,
    budget VARCHAR(20) NOT NULL,
    tipo_esperienza VARCHAR(50) NOT NULL,
    numero_viaggiatori INTEGER NOT NULL DEFAULT 1,
    note TEXT,
    
    -- Stato della prenotazione: 'in_attesa', 'confermata', 'rivelata', 'completata', 'annullata'
    stato VARCHAR(30) NOT NULL DEFAULT 'in_attesa',
    
    -- Data e ora in cui è stata fatta la prenotazione
    data_prenotazione TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    -- Vincoli di integrità referenziale
    CONSTRAINT fk_utente FOREIGN KEY (id_utente) REFERENCES utenti(id) ON DELETE CASCADE,
    CONSTRAINT fk_destinazione FOREIGN KEY (id_destinazione) REFERENCES destinazioni_misteriose(id) ON DELETE SET NULL
);

-- Creiamo un indice sull'id_utente per velocizzare le query "mostra le mie prenotazioni"
CREATE INDEX idx_prenotazioni_utente ON prenotazioni_misteriose(id_utente);

-- Creiamo un indice sul codice per velocizzare le ricerche per codice
CREATE INDEX idx_prenotazioni_codice ON prenotazioni_misteriose(codice);


-- Creazione tabella VIAGGI: contiene tutti i viaggi normali del sito
CREATE TABLE viaggi (
    id SERIAL PRIMARY KEY,
    
    -- Campi principali del viaggio
    mese VARCHAR(20) NOT NULL,
    periodo VARCHAR(50) NOT NULL,
    data_visualizzata VARCHAR(20) NOT NULL,
    destinazione VARCHAR(100) NOT NULL,
    prezzo INTEGER NOT NULL,
    
    -- Stato del viaggio: 'disponibile', 'sold_out', 'in_arrivo'
    stato VARCHAR(20) NOT NULL,
    
    -- Posti disponibili (0 se sold_out o se non rilevante)
    posti_disponibili INTEGER NOT NULL DEFAULT 0,
    -- Posti totali (per i viaggi in arrivo serve a mostrare "X posti totali")
    posti_totali INTEGER NOT NULL DEFAULT 0,
    
    -- Rotta frontend per il dettaglio (es. '/agosto_algeria'), può essere NULL
    rotta VARCHAR(100),
    
    -- Indica se il viaggio è ancora attivo (per disattivarlo senza cancellarlo)
    attivo BOOLEAN DEFAULT TRUE
);

-- Indice per velocizzare il filtro per stato (la query più frequente)
CREATE INDEX idx_viaggi_stato ON viaggi(stato);
CREATE INDEX idx_viaggi_mese ON viaggi(mese);

