-- Creazione tabella PRENOTAZIONI VIAGGI
CREATE TABLE prenotazioni_viaggi (
    id SERIAL PRIMARY KEY,
    codice VARCHAR(20) NOT NULL UNIQUE,
    id_utente BIGINT NOT NULL,
    id_viaggio INTEGER,
    numero_viaggiatori INTEGER NOT NULL DEFAULT 1,
    nome_completo VARCHAR(150) NOT NULL,
    email_contatto VARCHAR(150) NOT NULL,
    telefono VARCHAR(50),
    note TEXT,
    stato VARCHAR(30) NOT NULL DEFAULT 'in_attesa',
    data_prenotazione TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_utente_viaggio FOREIGN KEY (id_utente) REFERENCES utenti(id) ON DELETE CASCADE,
    CONSTRAINT fk_viaggio FOREIGN KEY (id_viaggio) REFERENCES viaggi(id) ON DELETE SET NULL
);

CREATE INDEX idx_prenotazioni_viaggi_utente ON prenotazioni_viaggi(id_utente);
CREATE INDEX idx_prenotazioni_viaggi_codice ON prenotazioni_viaggi(codice);



-- Aggiungiamo la colonna data_registrazione alla tabella utenti
ALTER TABLE utenti 
ADD COLUMN data_registrazione TIMESTAMP DEFAULT CURRENT_TIMESTAMP;

-- Aggiorniamo le righe esistenti (i tuoi utenti già registrati) con la data attuale come fallback
UPDATE utenti 
SET data_registrazione = CURRENT_TIMESTAMP 
WHERE data_registrazione IS NULL;


-- Aggiungiamo la colonna is_admin alla tabella utenti
-- Default FALSE: tutti gli utenti registrati sono normali, l'admin va promosso manualmente
ALTER TABLE utenti 
ADD COLUMN is_admin BOOLEAN DEFAULT FALSE NOT NULL;

-- Aggiorniamo le righe esistenti impostandole come non-admin (FALSE)
UPDATE utenti 
SET is_admin = FALSE 
WHERE is_admin IS NULL;

UPDATE utenti 
SET is_admin = TRUE 
WHERE username = 'Pulci26';


-- Creazione tabella MESSAGGI_CONTATTO: salva tutti i messaggi inviati dal form Contattaci
CREATE TABLE messaggi_contatto (
    id SERIAL PRIMARY KEY,
    
    -- Dati del mittente
    nome VARCHAR(150) NOT NULL,
    email VARCHAR(150) NOT NULL,
    telefono VARCHAR(50),
    
    -- Motivo del contatto (selezionato dal dropdown del form)
    motivo VARCHAR(100) NOT NULL,
    
    -- Testo del messaggio
    messaggio TEXT NOT NULL,
    
    -- Stato del messaggio: 'nuovo', 'letto', 'risolto'
    stato VARCHAR(20) NOT NULL DEFAULT 'nuovo',
    
    -- Collegamento all'utente (se loggato), altrimenti NULL per visitatori non loggati
    id_utente BIGINT,
    
    -- Data e ora di invio del messaggio
    data_invio TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    -- Foreign key facoltativa verso utenti (può essere NULL se utente non loggato)
    CONSTRAINT fk_utente_messaggio FOREIGN KEY (id_utente) REFERENCES utenti(id) ON DELETE SET NULL
);

-- Indice per velocizzare l'ordinamento per data nell'admin
CREATE INDEX idx_messaggi_data ON messaggi_contatto(data_invio DESC);
-- Indice per velocizzare il filtro per stato
CREATE INDEX idx_messaggi_stato ON messaggi_contatto(stato);


-- Creazione tabella RECENSIONI: salva le recensioni scritte dagli utenti
CREATE TABLE recensioni (
    id SERIAL PRIMARY KEY,
    
    -- Collegamento all'utente che ha scritto la recensione
    id_utente BIGINT NOT NULL,
    
    -- Numero di stelle: da 1 a 5
    stelle INTEGER NOT NULL CHECK (stelle BETWEEN 1 AND 5),
    
    -- Titolo della recensione (breve)
    titolo VARCHAR(150) NOT NULL,
    
    -- Testo della recensione
    testo TEXT NOT NULL,
    
    -- Stato della recensione: 'in_attesa' (da approvare), 'pubblicata', 'nascosta'
    stato VARCHAR(20) NOT NULL DEFAULT 'in_attesa',
    
    -- Data di creazione della recensione
    data_creazione TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    
    -- Foreign key verso utenti: se l'utente viene cancellato, anche le recensioni vanno via
    CONSTRAINT fk_utente_recensione FOREIGN KEY (id_utente) REFERENCES utenti(id) ON DELETE CASCADE
);

-- Indice per velocizzare la query "mostra solo recensioni pubblicate"
CREATE INDEX idx_recensioni_stato ON recensioni(stato);
-- Indice per ordinare per data (recenti prima)
CREATE INDEX idx_recensioni_data ON recensioni(data_creazione DESC);


