-- ============ ID 25: TROMSO ============
UPDATE viaggi SET 
descrizione = 'Tromsø è la porta d''ingresso al mondo artico: una città vivace circondata da fiordi mozzafiato, montagne innevate e cieli che, durante l''inverno, si tingono di verde e viola con l''Aurora Boreale. In questa avventura ti porteremo a esplorare la natura selvaggia della Norvegia del Nord, tra escursioni con cani da slitta, safari per avvistare le balene, gite in motoslitta tra le foreste innevate e ovviamente notti di caccia all''Aurora Boreale. Tromsø è il punto perfetto da cui partire per vivere l''Artico in tutte le sue sfaccettature: paesaggi da sogno, esperienze adrenaliniche e momenti di pura magia sotto il cielo del Nord.',
itinerario = '[
  {"titolo": "Day 1: Arrivo a Tromsø", "immagine": "/Sfondo.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Partenza dall''Italia con voli con scalo per Tromsø. Arrivo in città, trasferimento in hotel e check-in.<br><br><b>Sera:</b> Prima passeggiata nella città artica e cena in un ristorante locale per assaggiare i sapori della Norvegia del Nord."},
  {"titolo": "Day 2: Tromsø e prima caccia all''Aurora", "immagine": "/Sfondo2.jpg", "testo": "<b>Mattina:</b> Visita guidata di Tromsø: la Cattedrale Artica, il porto, il Polaria Museum dedicato alla fauna polare.<br><br><b>Pomeriggio:</b> Salita con la funivia Fjellheisen per ammirare il panorama mozzafiato sulla città e i fiordi circostanti.<br><br><b>Sera:</b> Prima uscita serale a caccia dell''Aurora Boreale, lontano dalle luci della città."},
  {"titolo": "Day 3: Husky Sledding", "immagine": "/Sfondo3.jpg", "testo": "<b>Mattina:</b> Trasferimento al camp degli husky e indimenticabile escursione in slitta trainata dai cani attraverso paesaggi innevati e foreste artiche.<br><br><b>Pomeriggio:</b> Pranzo nel camp, possibilità di coccolare i cuccioli di husky e tempo libero per godersi l''atmosfera nordica.<br><br><b>Sera:</b> Rientro a Tromsø, cena e seconda uscita a caccia dell''Aurora Boreale."},
  {"titolo": "Day 4: Whale Watching", "immagine": "/Sfondo4.jpg", "testo": "<b>Mattina:</b> Partenza in barca per il safari delle balene: con un po'' di fortuna, possibilità di avvistare orche e megattere che ogni inverno popolano i fiordi norvegesi.<br><br><b>Pomeriggio:</b> Pranzo a bordo e rientro al porto di Tromsø.<br><br><b>Sera:</b> Cena tipica e terza uscita opzionale a caccia dell''Aurora Boreale."},
  {"titolo": "Day 5: Motoslitta nelle foreste artiche", "immagine": "/Sfondo.jpg", "testo": "<b>Mattina:</b> Trasferimento al camp e avventura adrenalinica in motoslitta self-drive tra foreste innevate e altopiani artici.<br><br><b>Pomeriggio:</b> Pranzo tradizionale Sami in tenda, con racconti sulla cultura del popolo nomade del Nord.<br><br><b>Sera:</b> Rientro a Tromsø e ultima caccia all''Aurora Boreale."},
  {"titolo": "Day 6: Rientro in Italia", "immagine": "/Sfondo2.jpg", "testo": "<b>Mattina:</b> Tempo libero a Tromsø per gli ultimi acquisti o passeggiate.<br><br><b>Pomeriggio:</b> Trasferimento all''aeroporto e volo di rientro per l''Italia… alla prossima avventura!"}
]'::jsonb,
foto_header = '/Sfondo3.jpg',
galleria_foto = ARRAY['/Sfondo.jpg', '/Sfondo2.jpg', '/Sfondo3.jpg']
WHERE id = 25;

-- ============ ID 26: MESSICO ============
UPDATE viaggi SET 
descrizione = 'Il Messico è una terra di contrasti e meraviglie, dove storia millenaria, culture antiche e paesaggi naturali mozzafiato si incontrano in un mix unico al mondo. Dalle imponenti piramidi Maya di Chichén Itzá alle spiagge caraibiche di Holbox, dalle città coloniali alle giungle dello Yucatán, il Messico ti regalerà esperienze indimenticabili. Esploreremo cenotes nascosti, rovine archeologiche, mercati colorati e la vivace vita notturna delle città turistiche. Un viaggio che è insieme avventura, cultura e relax, perfetto per chi cerca un''esperienza completa nel cuore dell''America Latina.',
itinerario = '[
  {"titolo": "Day 1: Arrivo a Cancún", "immagine": "/Cancun.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Partenza dall''Italia con voli per Cancún. Arrivo, trasferimento in hotel e check-in.<br><br><b>Sera:</b> Prima cena messicana e serata libera nella zona alberghiera di Cancún."},
  {"titolo": "Day 2: Chichén Itzá", "immagine": "/ChichenItza.jpg", "testo": "<b>Mattina:</b> Partenza presto per la visita di Chichén Itzá, una delle Sette Meraviglie del Mondo, con la maestosa piramide di Kukulkán.<br><br><b>Pomeriggio:</b> Pranzo tipico Yucateco e bagno rinfrescante in un cenote, le piscine naturali sacre dei Maya.<br><br><b>Sera:</b> Rientro a Cancún, cena e relax in hotel."},
  {"titolo": "Day 3: Isola di Holbox", "immagine": "/Holbox.jpg", "testo": "<b>Mattina:</b> Trasferimento all''isola di Holbox, paradiso caraibico con spiagge bianche e acque turchesi.<br><br><b>Pomeriggio:</b> Tour in barca per esplorare i tre punti più suggestivi dell''isola: Punta Mosquito, Cabo Catoche e Isla Pájaros.<br><br><b>Sera:</b> Cena con i piedi nella sabbia in uno dei tipici ristoranti dell''isola."},
  {"titolo": "Day 4: Cancún e Tulum", "immagine": "/Messico.jpg", "testo": "<b>Mattina:</b> Rientro da Holbox a Cancún e partenza per Tulum.<br><br><b>Pomeriggio:</b> Visita delle rovine Maya di Tulum, uniche per la loro posizione a strapiombo sul mar dei Caraibi. Bagno nella spiaggia di Tulum.<br><br><b>Sera:</b> Cena e serata nei locali di Tulum."},
  {"titolo": "Day 5: Cenotes e relax", "immagine": "/Messico2.jpg", "testo": "<b>Mattina:</b> Tour dei cenotes più belli della Riviera Maya: Gran Cenote, Dos Ojos e Cenote Azul.<br><br><b>Pomeriggio:</b> Snorkeling nei cenotes e pranzo locale.<br><br><b>Sera:</b> Rientro in hotel, cena e serata libera."},
  {"titolo": "Day 6: Rientro in Italia", "immagine": "/Cancun.jpg", "testo": "<b>Mattina:</b> Tempo libero per ultimi acquisti o relax in spiaggia.<br><br><b>Pomeriggio:</b> Trasferimento all''aeroporto di Cancún e volo di rientro… alla prossima avventura!"}
]'::jsonb,
foto_header = '/Messico.jpg',
galleria_foto = ARRAY['/ChichenItza.jpg', '/Holbox.jpg', '/Cancun.jpg']
WHERE id = 26;

-- ============ ID 27: UGANDA ============
UPDATE viaggi SET 
descrizione = 'L''Uganda, definita da Winston Churchill «la perla d''Africa», è un Paese sorprendente, ancora poco conosciuto dal turismo di massa. Dalle foreste pluviali abitate dai gorilla di montagna ai laghi sterminati, dai parchi nazionali brulicanti di fauna selvaggia alle cascate impetuose del Nilo, l''Uganda ti regalerà esperienze autentiche e indimenticabili. Faremo trekking sulle montagne di Bwindi alla ricerca dei gorilla, safari nei parchi nazionali per avvistare i grandi mammiferi africani, e visiteremo la cultura unica del popolo ugandese, tra sorrisi accoglienti e paesaggi mozzafiato.',
itinerario = '[
  {"titolo": "Day 1: Arrivo a Entebbe", "immagine": "/Nairobi.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Partenza dall''Italia con voli per Entebbe. Arrivo, trasferimento in hotel e check-in.<br><br><b>Sera:</b> Cena in hotel sulle rive del Lago Vittoria."},
  {"titolo": "Day 2: Murchison Falls National Park", "immagine": "/Loiyangalani.jpg", "testo": "<b>Mattina:</b> Partenza per il Murchison Falls National Park, il parco nazionale più grande dell''Uganda.<br><br><b>Pomeriggio:</b> Game drive pomeridiano per avvistare elefanti, giraffe, leoni e antilopi.<br><br><b>Sera:</b> Cena al lodge nel cuore del parco."},
  {"titolo": "Day 3: Cascate e Nilo", "immagine": "/Nairobi2.jpg", "testo": "<b>Mattina:</b> Game drive mattutino e poi crociera sul Nilo Vittoria fino alle spettacolari Cascate di Murchison.<br><br><b>Pomeriggio:</b> Trekking fino alla sommità delle cascate per ammirare il salto di 43 metri.<br><br><b>Sera:</b> Rientro al lodge, cena e serata sotto le stelle."},
  {"titolo": "Day 4: Bwindi Forest", "immagine": "/Loiyangalani.jpg", "testo": "<b>Mattina:</b> Trasferimento verso la Bwindi Impenetrable Forest, sito UNESCO e habitat dei gorilla di montagna.<br><br><b>Pomeriggio:</b> Arrivo al lodge nella foresta, briefing per il trekking del giorno successivo.<br><br><b>Sera:</b> Cena al lodge e serata tra i suoni della foresta."},
  {"titolo": "Day 5: Trekking dei Gorilla", "immagine": "/Nairobi.jpg", "testo": "<b>Mattina:</b> Esperienza unica: trekking nella foresta alla ricerca dei gorilla di montagna. L''incontro con questi animali maestosi è un''esperienza che cambia la vita.<br><br><b>Pomeriggio:</b> Rientro al lodge, pranzo e relax.<br><br><b>Sera:</b> Cena celebrativa e brindisi alla giornata indimenticabile."},
  {"titolo": "Day 6: Rientro in Italia", "immagine": "/Nairobi2.jpg", "testo": "<b>Mattina:</b> Trasferimento all''aeroporto di Entebbe.<br><br><b>Pomeriggio:</b> Volo di rientro per l''Italia… alla prossima avventura!"}
]'::jsonb,
foto_header = '/Loiyangalani.jpg',
galleria_foto = ARRAY['/Loiyangalani.jpg', '/Nairobi.jpg', '/Nairobi2.jpg']
WHERE id = 27;

-- ============ ID 28: REPUBBLICA DOMINICANA ============
UPDATE viaggi SET 
descrizione = 'La Repubblica Dominicana è il sogno di ogni amante del mare: spiagge di sabbia bianca infinita, palme che si affacciano su acque turchesi, barriere coralline ricchissime e un''atmosfera caraibica unica al mondo. Ma oltre alle celebri spiagge di Punta Cana e Bayahibe, scopriremo anche il fascino coloniale di Santo Domingo, prima città fondata dagli europei nelle Americhe, e l''isola paradisiaca di Saona, perla dei Caraibi. Un mix perfetto di relax, cultura, snorkeling e divertimento sotto il sole tropicale.',
itinerario = '[
  {"titolo": "Day 1: Arrivo a Santo Domingo", "immagine": "/Santodomingo.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Partenza dall''Italia e arrivo a Santo Domingo, trasferimento in hotel.<br><br><b>Sera:</b> Cena nella Zona Coloniale e prima passeggiata nel centro storico patrimonio UNESCO."},
  {"titolo": "Day 2: Santo Domingo coloniale", "immagine": "/Santodomingo2.jpg", "testo": "<b>Mattina:</b> Visita guidata della Zona Coloniale: Cattedrale Primada de America, Alcázar de Colón, Calle Las Damas.<br><br><b>Pomeriggio:</b> Visita del Faro a Colón e tempo libero per esplorare la città.<br><br><b>Sera:</b> Cena tipica dominicana e serata di musica merengue."},
  {"titolo": "Day 3: Bayahibe", "immagine": "/Bayahibe.jpg", "testo": "<b>Mattina:</b> Trasferimento a Bayahibe, villaggio di pescatori sulla costa caraibica.<br><br><b>Pomeriggio:</b> Pomeriggio in spiaggia a Bayahibe, una delle più belle dei Caraibi.<br><br><b>Sera:</b> Cena di pesce fresco con vista sul mare."},
  {"titolo": "Day 4: Isla Saona", "immagine": "/IslaSaona.jpg", "testo": "<b>Mattina:</b> Escursione in catamarano verso Isla Saona, paradiso protetto del Parque Nacional Cotubanamá.<br><br><b>Pomeriggio:</b> Pranzo a buffet sulla spiaggia, snorkeling e tempo libero in spiaggia.<br><br><b>Sera:</b> Rientro a Bayahibe in motoscafo, cena e serata."},
  {"titolo": "Day 5: Punta Cana", "immagine": "/PuntaCana.jpg", "testo": "<b>Mattina:</b> Trasferimento a Punta Cana, capitale del turismo balneare dominicano.<br><br><b>Pomeriggio:</b> Pomeriggio di puro relax sulle spiagge di Bávaro.<br><br><b>Sera:</b> Cena in resort all-inclusive e serata di animazione."},
  {"titolo": "Day 6: Rientro in Italia", "immagine": "/PuntaCana.jpg", "testo": "<b>Mattina:</b> Ultima mattinata in spiaggia.<br><br><b>Pomeriggio:</b> Trasferimento all''aeroporto e volo di rientro… alla prossima avventura!"}
]'::jsonb,
foto_header = '/IslaSaona.jpg',
galleria_foto = ARRAY['/Bayahibe.jpg', '/IslaSaona.jpg', '/PuntaCana.jpg']
WHERE id = 28;

-- ============ ID 29: AUSTRALIA ============
UPDATE viaggi SET 
descrizione = 'L''Australia è un continente intero da scoprire: dalle metropoli vibranti come Melbourne e Sydney alle spiagge dorate della Gold Coast, dalle distese rosse del Outback alla Great Barrier Reef, una delle meraviglie naturali più spettacolari del pianeta. In questo viaggio attraverseremo i paesaggi più iconici della costa orientale, faremo snorkeling nella barriera corallina, surferemo (o ci proveremo!) sulle onde della Gold Coast e scopriremo la cultura urbana e gastronomica delle grandi città. Un''avventura indimenticabile «Down Under»!',
itinerario = '[
  {"titolo": "Day 1: Arrivo a Sydney", "immagine": "/Queensland.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Lungo volo dall''Italia con scalo. Arrivo a Sydney, trasferimento in hotel.<br><br><b>Sera:</b> Recupero del jet lag con cena leggera e prima passeggiata al porto."},
  {"titolo": "Day 2: Sydney highlights", "immagine": "/Melbourne.jpg", "testo": "<b>Mattina:</b> Visita dell''Opera House e dell''Harbour Bridge, simboli della città.<br><br><b>Pomeriggio:</b> Bondi Beach e passeggiata costiera fino a Coogee.<br><br><b>Sera:</b> Cena al Darling Harbour, vivace zona del porto."},
  {"titolo": "Day 3: Volo per Cairns e Great Barrier Reef", "immagine": "/Queensland.jpg", "testo": "<b>Mattina:</b> Volo interno per Cairns, porta d''ingresso alla Great Barrier Reef.<br><br><b>Pomeriggio:</b> Pomeriggio di snorkeling nella barriera corallina più famosa al mondo.<br><br><b>Sera:</b> Cena di pesce fresco a Cairns."},
  {"titolo": "Day 4: Gold Coast e surf", "immagine": "/GoldCoast.jpg", "testo": "<b>Mattina:</b> Volo per Gold Coast, capitale del surf australiano.<br><br><b>Pomeriggio:</b> Lezione di surf opzionale o relax sulla spiaggia di Surfers Paradise.<br><br><b>Sera:</b> Cena e serata nei locali della Gold Coast."},
  {"titolo": "Day 5: Melbourne", "immagine": "/Melbourne.jpg", "testo": "<b>Mattina:</b> Volo per Melbourne, capitale culturale dell''Australia.<br><br><b>Pomeriggio:</b> Visita dei laneways, le caratteristiche stradine con street art e caffetterie.<br><br><b>Sera:</b> Cena nel quartiere multiculturale di Fitzroy."},
  {"titolo": "Day 6: Rientro in Italia", "immagine": "/GoldCoast.jpg", "testo": "<b>Mattina:</b> Tempo libero a Melbourne.<br><br><b>Pomeriggio:</b> Trasferimento all''aeroporto e lungo volo di rientro... alla prossima avventura!"}
]'::jsonb,
foto_header = '/GoldCoast.jpg',
galleria_foto = ARRAY['/GoldCoast.jpg', '/Melbourne.jpg', '/Queensland.jpg']
WHERE id = 29;

-- ============ ID 30: CAMBOGIA ============
UPDATE viaggi SET 
descrizione = 'La Cambogia è una terra di templi millenari, sorrisi caldi e storia profonda. Cuore del viaggio è Angkor Wat, il complesso templare più grande al mondo, capolavoro dell''architettura Khmer dichiarato patrimonio UNESCO. Ma la Cambogia è anche Phnom Penh, capitale dal passato doloroso ma dal presente vibrante, le campagne verdeggianti tra risaie e villaggi galleggianti, e le coste ancora autentiche del Golfo di Thailandia. Un viaggio che è insieme spiritualità, storia e calore umano.',
itinerario = '[
  {"titolo": "Day 1: Arrivo a Phnom Penh", "immagine": "/PhnomPenh.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Volo dall''Italia con scalo. Arrivo a Phnom Penh, trasferimento in hotel.<br><br><b>Sera:</b> Cena in centro e prima passeggiata sul lungofiume."},
  {"titolo": "Day 2: Phnom Penh", "immagine": "/PhnomPenh.jpg", "testo": "<b>Mattina:</b> Visita del Palazzo Reale e della Pagoda d''Argento.<br><br><b>Pomeriggio:</b> Visita toccante del Tuol Sleng Genocide Museum e dei Killing Fields, per comprendere la dolorosa storia recente del paese.<br><br><b>Sera:</b> Cena in ristorante locale."},
  {"titolo": "Day 3: Volo per Siem Reap", "immagine": "/Cambogia.jpg", "testo": "<b>Mattina:</b> Volo interno per Siem Reap, base per la visita di Angkor.<br><br><b>Pomeriggio:</b> Visita del villaggio galleggiante di Tonle Sap, sul lago più grande del Sud-Est asiatico.<br><br><b>Sera:</b> Cena con spettacolo di danza Apsara tradizionale."},
  {"titolo": "Day 4: Angkor Wat", "immagine": "/AngkorWat.jpg", "testo": "<b>Mattina:</b> Sveglia all''alba per ammirare l''iconico sorgere del sole su Angkor Wat. Visita guidata del tempio principale.<br><br><b>Pomeriggio:</b> Visita di Angkor Thom e del tempio del Bayon con i suoi 216 volti scolpiti.<br><br><b>Sera:</b> Cena e serata a Pub Street, vivace zona di Siem Reap."},
  {"titolo": "Day 5: Templi nascosti", "immagine": "/Cambogia2.jpg", "testo": "<b>Mattina:</b> Visita di Ta Prohm, il «tempio della giungla» avvolto dalle radici di alberi giganti.<br><br><b>Pomeriggio:</b> Visita del tempio rosa Banteay Srei e relax in piscina.<br><br><b>Sera:</b> Cena di addio e ultima serata a Siem Reap."},
  {"titolo": "Day 6: Rientro in Italia", "immagine": "/Cambogia3.jpg", "testo": "<b>Mattina:</b> Trasferimento all''aeroporto.<br><br><b>Pomeriggio:</b> Volo di rientro per l''Italia… alla prossima avventura!"}
]'::jsonb,
foto_header = '/AngkorWat.jpg',
galleria_foto = ARRAY['/AngkorWat.jpg', '/Cambogia.jpg', '/PhnomPenh.jpg']
WHERE id = 30;

-- ============ ID 31: FILIPPINE ============
UPDATE viaggi SET 
descrizione = 'Le Filippine sono un arcipelago di oltre 7.000 isole, ognuna con la sua identità unica. In questo viaggio esploreremo le perle delle Filippine: dalla vivace capitale Manila alle spiagge da cartolina di El Nido e Coron a Palawan, dichiarata da molti la più bella isola del mondo. Faremo island hopping tra lagune segrete, snorkeling nei relitti della Seconda Guerra Mondiale, e visiteremo le iconiche Chocolate Hills di Bohol. Un viaggio tra cultura ispanica, sorrisi filippini e paradisi tropicali ancora poco conosciuti dal turismo di massa.',
itinerario = '[
  {"titolo": "Day 1: Arrivo a Manila", "immagine": "/Manila.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Volo dall''Italia con scalo. Arrivo a Manila, capitale delle Filippine, e check-in in hotel.<br><br><b>Sera:</b> Cena di benvenuto e prima esplorazione di Intramuros, il centro storico spagnolo."},
  {"titolo": "Day 2: Manila", "immagine": "/Manila2.jpg", "testo": "<b>Mattina:</b> Visita di Intramuros: Fort Santiago, San Agustín Church.<br><br><b>Pomeriggio:</b> Visita del Rizal Park e shopping nei moderni mall di Makati.<br><br><b>Sera:</b> Cena in ristorante con cucina tipica filippina."},
  {"titolo": "Day 3: Volo per Bohol", "immagine": "/Bohol.jpg", "testo": "<b>Mattina:</b> Volo interno per Bohol.<br><br><b>Pomeriggio:</b> Visita delle famose Chocolate Hills, oltre 1.000 colline di forma conica che a fine stagione si tingono di marrone.<br><br><b>Sera:</b> Cena tipica e relax in resort."},
  {"titolo": "Day 4: Coron", "immagine": "/Coron.jpg", "testo": "<b>Mattina:</b> Volo per Coron, paradiso di Palawan.<br><br><b>Pomeriggio:</b> Island hopping per scoprire Twin Lagoon e Kayangan Lake, considerato il lago più pulito delle Filippine.<br><br><b>Sera:</b> Cena di pesce fresco a Coron Town."},
  {"titolo": "Day 5: El Nido", "immagine": "/ElNido.jpg", "testo": "<b>Mattina:</b> Trasferimento via terra/barca a El Nido.<br><br><b>Pomeriggio:</b> Tour A delle isole più famose: Big Lagoon, Small Lagoon, Secret Lagoon, Shimizu Island.<br><br><b>Sera:</b> Cena con i piedi nella sabbia."},
  {"titolo": "Day 6: Rientro in Italia", "immagine": "/PuertoPrincesa.jpg", "testo": "<b>Mattina:</b> Trasferimento all''aeroporto di Puerto Princesa.<br><br><b>Pomeriggio:</b> Volo per Manila e poi volo di rientro per l''Italia… alla prossima avventura!"}
]'::jsonb,
foto_header = '/ElNido.jpg',
galleria_foto = ARRAY['/ElNido.jpg', '/Coron.jpg', '/Manila.jpg']
WHERE id = 31;

-- ============ ID 32: PALMA DI MALLORCA ============
UPDATE viaggi SET 
descrizione = 'Palma di Mallorca è la perla delle Baleari: una città elegante con un centro storico medievale, circondata da spiagge mozzafiato, calette nascoste e villaggi pittoreschi tra le montagne della Serra de Tramuntana. In questo viaggio scopriremo l''anima autentica dell''isola: dalle stradine di Palma con la maestosa Cattedrale gotica La Seu, alle spiagge cristalline di Cala d''Or e Cala Mondragó, fino ai villaggi di pescatori come Port de Sóller. Un mix perfetto di mare, cultura, gastronomia e divertimento mediterraneo.',
itinerario = '[
  {"titolo": "Day 1: Arrivo a Palma", "immagine": "/Palma.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Volo diretto dall''Italia per Palma di Mallorca. Arrivo, trasferimento in hotel e check-in.<br><br><b>Sera:</b> Prima passeggiata nel centro di Palma e cena in tapas bar."},
  {"titolo": "Day 2: Palma highlights", "immagine": "/Palma2.jpg", "testo": "<b>Mattina:</b> Visita della Cattedrale La Seu, capolavoro gotico affacciato sul mare, e del Palazzo Reale dell''Almudaina.<br><br><b>Pomeriggio:</b> Esplorazione del centro storico di Palma, tra case nobiliari e patio nascosti.<br><br><b>Sera:</b> Cena in ristorante con cucina maiorchina."},
  {"titolo": "Day 3: Serra de Tramuntana", "immagine": "/Palma3.jpg", "testo": "<b>Mattina:</b> Tour della Serra de Tramuntana, patrimonio UNESCO. Visita di Valldemossa, dove soggiornarono Chopin e George Sand.<br><br><b>Pomeriggio:</b> Discesa a Port de Sóller con il caratteristico tram d''epoca.<br><br><b>Sera:</b> Cena di pesce nel porto."},
  {"titolo": "Day 4: Cale del sud", "immagine": "/Palma4.jpg", "testo": "<b>Mattina:</b> Giornata al mare alla scoperta delle calette del sud-est: Cala d''Or, Cala Mondragó.<br><br><b>Pomeriggio:</b> Pranzo in chiringuito e relax in spiaggia.<br><br><b>Sera:</b> Cena in agriturismo con cucina contadina maiorchina."},
  {"titolo": "Day 5: Grotte e mare", "immagine": "/Palma5.jpg", "testo": "<b>Mattina:</b> Visita delle suggestive Cuevas del Drach, grotte sotterranee con uno dei più grandi laghi sotterranei al mondo.<br><br><b>Pomeriggio:</b> Pomeriggio in spiaggia.<br><br><b>Sera:</b> Cena d''addio e serata a Palma."},
  {"titolo": "Day 6: Rientro in Italia", "immagine": "/Palma6.jpg", "testo": "<b>Mattina:</b> Tempo libero per shopping o relax.<br><br><b>Pomeriggio:</b> Trasferimento all''aeroporto e volo di rientro… alla prossima avventura!"}
]'::jsonb,
foto_header = '/Palma.jpg',
galleria_foto = ARRAY['/Palma.jpg', '/Palma2.jpg', '/Palma5.jpg']
WHERE id = 32;

-- ============ ID 33: INDIA ============
UPDATE viaggi SET 
descrizione = 'L''India è un universo a sé: una terra di colori intensi, profumi inebrianti, spiritualità millenaria e contrasti forti che lasciano un''impronta indelebile in chi la visita. In questo viaggio esploreremo il celebre «Triangolo d''Oro»: Delhi, capitale caotica e affascinante; Agra con il maestoso Taj Mahal, monumento all''amore eterno; e Jaipur, la città rosa, capitale del Rajasthan. Un viaggio tra palazzi maharaja, mercati di spezie, templi sacri e l''incredibile umanità che popola questo Paese unico al mondo.',
itinerario = '[
  {"titolo": "Day 1: Arrivo a Delhi", "immagine": "/Delhi.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Volo dall''Italia per Delhi. Arrivo e trasferimento in hotel.<br><br><b>Sera:</b> Recupero dal viaggio e cena in hotel."},
  {"titolo": "Day 2: Delhi", "immagine": "/Delhi2.jpg", "testo": "<b>Mattina:</b> Visita di Old Delhi: Jama Masjid, la Moschea più grande dell''India, e tour in risciò nel bazaar di Chandni Chowk.<br><br><b>Pomeriggio:</b> Visita di New Delhi: India Gate, Qutub Minar e il Tempio del Loto.<br><br><b>Sera:</b> Cena con cucina tipica del Punjab."},
  {"titolo": "Day 3: Agra e Taj Mahal", "immagine": "/Jaipur.jpg", "testo": "<b>Mattina:</b> Trasferimento ad Agra in treno espresso.<br><br><b>Pomeriggio:</b> Visita del Taj Mahal al tramonto, una delle Sette Meraviglie del Mondo.<br><br><b>Sera:</b> Cena in hotel con vista del Taj."},
  {"titolo": "Day 4: Forte di Agra e Jaipur", "immagine": "/Jodhpur.jpg", "testo": "<b>Mattina:</b> Visita del Forte Rosso di Agra e di Fatehpur Sikri, antica capitale moghul abbandonata.<br><br><b>Pomeriggio:</b> Trasferimento a Jaipur, la «città rosa».<br><br><b>Sera:</b> Cena tipica del Rajasthan con musica e danza folk."},
  {"titolo": "Day 5: Jaipur", "immagine": "/Jaipur.jpg", "testo": "<b>Mattina:</b> Salita all''Amber Fort a dorso di elefante, visita del Palazzo dei Venti e dell''osservatorio astronomico Jantar Mantar.<br><br><b>Pomeriggio:</b> Shopping nei vivaci bazaar di Jaipur tra spezie, tessuti e gioielli.<br><br><b>Sera:</b> Cena d''addio in palazzo storico."},
  {"titolo": "Day 6: Rientro in Italia", "immagine": "/Delhi.jpg", "testo": "<b>Mattina:</b> Volo interno per Delhi.<br><br><b>Pomeriggio:</b> Trasferimento all''aeroporto internazionale e volo di rientro… alla prossima avventura!"}
]'::jsonb,
foto_header = '/Jaipur.jpg',
galleria_foto = ARRAY['/Jaipur.jpg', '/Delhi.jpg', '/Jodhpur.jpg']
WHERE id = 33;

-- ============ ID 34: KENYA ============
UPDATE viaggi SET 
descrizione = 'Il Kenya è la terra del safari per eccellenza: sterminate savane abitate dai «big five» (leoni, leopardi, elefanti, rinoceronti e bufali), il maestoso fenomeno della Grande Migrazione nel Masai Mara, e una costa indiana di sabbie bianche e barriere coralline. In questo viaggio vivremo l''Africa più autentica: safari fotografici nei parchi nazionali più famosi, incontri con la cultura Masai, paesaggi sconfinati e tramonti che restano nel cuore. Un''avventura emozionante tra natura selvaggia e calore umano.',
itinerario = '[
  {"titolo": "Day 1: Arrivo a Nairobi", "immagine": "/Nairobi.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Volo dall''Italia per Nairobi, capitale del Kenya. Trasferimento in hotel.<br><br><b>Sera:</b> Cena di benvenuto e briefing sul safari."},
  {"titolo": "Day 2: Amboseli National Park", "immagine": "/Loiyangalani.jpg", "testo": "<b>Mattina:</b> Partenza per l''Amboseli National Park, ai piedi del Kilimangiaro.<br><br><b>Pomeriggio:</b> Primo game drive con avvistamenti di elefanti, sullo sfondo della maestosa montagna.<br><br><b>Sera:</b> Cena al lodge tra i suoni della savana."},
  {"titolo": "Day 3: Lago Nakuru", "immagine": "/Nairobi2.jpg", "testo": "<b>Mattina:</b> Trasferimento al Lago Nakuru, famoso per i fenicotteri rosa.<br><br><b>Pomeriggio:</b> Game drive nel parco con possibilità di avvistare i rari rinoceronti bianchi e neri.<br><br><b>Sera:</b> Cena al lodge."},
  {"titolo": "Day 4: Masai Mara", "immagine": "/Loiyangalani.jpg", "testo": "<b>Mattina:</b> Trasferimento al Masai Mara National Reserve, il parco più famoso del Kenya.<br><br><b>Pomeriggio:</b> Game drive pomeridiano alla ricerca dei big five.<br><br><b>Sera:</b> Cena al camp e serata sotto le stelle africane."},
  {"titolo": "Day 5: Masai Mara intera giornata", "immagine": "/Nairobi.jpg", "testo": "<b>Mattina:</b> Game drive all''alba, momento migliore per gli avvistamenti.<br><br><b>Pomeriggio:</b> Visita di un villaggio Masai per conoscere usi e tradizioni di questa antica popolazione.<br><br><b>Sera:</b> Cena celebrativa al camp."},
  {"titolo": "Day 6: Rientro in Italia", "immagine": "/Nairobi2.jpg", "testo": "<b>Mattina:</b> Ultimo game drive e trasferimento a Nairobi.<br><br><b>Pomeriggio:</b> Volo di rientro per l''Italia… alla prossima avventura!"}
]'::jsonb,
foto_header = '/Nairobi.jpg',
galleria_foto = ARRAY['/Nairobi.jpg', '/Loiyangalani.jpg', '/Nairobi2.jpg']
WHERE id = 34;

-- ============ ID 35: ZANZIBAR ============
UPDATE viaggi SET 
descrizione = 'Zanzibar è il paradiso dell''Oceano Indiano: spiagge bianchissime lambite da acque turchesi, atolli coralli ricchi di vita marina, foreste di spezie profumate e una storia millenaria che fonde tradizioni africane, arabe e indiane. In questo viaggio scopriremo Stone Town, il cuore storico patrimonio UNESCO, faremo snorkeling nell''atollo di Mnemba, visiteremo le piantagioni di spezie e ci rilasseremo sulle spiagge da cartolina di Nungwi e Kendwa. Un viaggio tra cultura swahili, mare cristallino e tramonti spettacolari.',
itinerario = '[
  {"titolo": "Day 1: Arrivo a Zanzibar", "immagine": "/Nungwi.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Volo dall''Italia per Zanzibar. Trasferimento in resort sulla costa.<br><br><b>Sera:</b> Cena di benvenuto in resort, primo tramonto sull''Oceano Indiano."},
  {"titolo": "Day 2: Stone Town", "immagine": "/Mnemba.jpg", "testo": "<b>Mattina:</b> Visita guidata di Stone Town: il mercato di Darajani, la Casa delle Meraviglie, l''ex mercato degli schiavi.<br><br><b>Pomeriggio:</b> Esplorazione delle stradine di Stone Town con le caratteristiche porte intagliate, e tour del Forodhani Gardens.<br><br><b>Sera:</b> Cena di street food a Forodhani Night Market."},
  {"titolo": "Day 3: Spice Tour", "immagine": "/Menaibay.jpg", "testo": "<b>Mattina:</b> Spice Tour, visita guidata di una piantagione di spezie tra chiodi di garofano, vaniglia, cardamomo e cannella.<br><br><b>Pomeriggio:</b> Visita della Jozani Forest e incontro con le scimmie endemiche Red Colobus.<br><br><b>Sera:</b> Cena a base di pesce fresco."},
  {"titolo": "Day 4: Atollo di Mnemba", "immagine": "/Mnemba.jpg", "testo": "<b>Mattina:</b> Escursione in barca all''atollo di Mnemba per snorkeling tra pesci tropicali e coralli.<br><br><b>Pomeriggio:</b> Pranzo a base di pesce fresco e relax in spiaggia.<br><br><b>Sera:</b> Cena in resort e serata sotto le stelle."},
  {"titolo": "Day 5: Nungwi", "immagine": "/Nungwi.jpg", "testo": "<b>Mattina:</b> Trasferimento a Nungwi, spiaggia simbolo del nord di Zanzibar.<br><br><b>Pomeriggio:</b> Tempo libero in spiaggia, possibilità di sunset cruise in dhow tradizionale.<br><br><b>Sera:</b> Cena con vista tramonto."},
  {"titolo": "Day 6: Rientro in Italia", "immagine": "/Menaibay.jpg", "testo": "<b>Mattina:</b> Ultimo bagno nell''Oceano Indiano.<br><br><b>Pomeriggio:</b> Trasferimento all''aeroporto e volo di rientro… alla prossima avventura!"}
]'::jsonb,
foto_header = '/Nungwi.jpg',
galleria_foto = ARRAY['/Nungwi.jpg', '/Mnemba.jpg', '/Menaibay.jpg']
WHERE id = 35;

-- ============ ID 36: YEMEN ============
UPDATE viaggi SET 
descrizione = 'Lo Yemen è uno dei Paesi più affascinanti e meno conosciuti al mondo: una terra di antiche città fortificate in mattoni di fango, paesaggi mozzafiato che spaziano dalle montagne alle spiagge dell''Oceano Indiano, e l''isola di Socotra, definita il «Galápagos dell''Oceano Indiano» per la sua biodiversità unica al mondo. In questo viaggio esclusivo scopriremo la cultura millenaria yemenita, i mercati profumati di incenso e mirra, e i paesaggi alieni di Socotra con i suoi celebri alberi di sangue di drago. Un''avventura per veri esploratori.',
itinerario = '[
  {"titolo": "Day 1: Arrivo a Mukalla", "immagine": "/Mukalla.jpg", "testo": "<b>Mattina/Pomeriggio:</b> Volo dall''Italia con scalo per Mukalla, città costiera dello Yemen.<br><br><b>Sera:</b> Trasferimento in hotel, cena di benvenuto e briefing."},
  {"titolo": "Day 2: Mukalla", "immagine": "/Mukalla.jpg", "testo": "<b>Mattina:</b> Visita di Mukalla, perla dell''Oceano Indiano con la sua medina e il porto.<br><br><b>Pomeriggio:</b> Esplorazione del souk e del lungomare.<br><br><b>Sera:</b> Cena in ristorante locale con cucina yemenita."},
  {"titolo": "Day 3: Volo per Socotra", "immagine": "/Mukalla.jpg", "testo": "<b>Mattina:</b> Volo per Socotra, isola unica al mondo per biodiversità.<br><br><b>Pomeriggio:</b> Visita degli iconici alberi di sangue di drago al Diksam Plateau.<br><br><b>Sera:</b> Cena al camp e prima serata sotto un cielo stellato incredibile."},
  {"titolo": "Day 4: Socotra natura", "immagine": "/Mukalla.jpg", "testo": "<b>Mattina:</b> Escursione alle dune di Arher e bagno nelle acque cristalline.<br><br><b>Pomeriggio:</b> Trekking nella Wadi Dirhur e visita delle piscine naturali.<br><br><b>Sera:</b> Cena al camp."},
  {"titolo": "Day 5: Spiagge di Socotra", "immagine": "/Mukalla.jpg", "testo": "<b>Mattina:</b> Visita della laguna di Detwah, una delle spiagge più belle al mondo.<br><br><b>Pomeriggio:</b> Snorkeling nelle acque dell''isola.<br><br><b>Sera:</b> Cena d''addio."},
  {"titolo": "Day 6: Rientro in Italia", "immagine": "/Mukalla.jpg", "testo": "<b>Mattina:</b> Volo da Socotra a Mukalla.<br><br><b>Pomeriggio:</b> Volo di rientro per l''Italia… alla prossima avventura!"}
]'::jsonb,
foto_header = '/Mukalla.jpg',
galleria_foto = ARRAY['/Mukalla.jpg', '/Mukalla.jpg', '/Mukalla.jpg']
WHERE id = 36;

-- ==========================================
-- VERIFICA FINALE
-- ==========================================
SELECT id, mese, destinazione,
       LENGTH(descrizione) AS lunghezza_descrizione,
       jsonb_array_length(itinerario) AS giorni_itinerario,
       array_length(galleria_foto, 1) AS num_foto,
       foto_header
FROM viaggi 
WHERE stato = 'in_arrivo'
ORDER BY id;


